class Solution {
    public int kthInTable(int rows, int cols, int k) {
        int[] vals = new int[rows * cols];
        int t = 0;
        for (int i = 1; i <= rows; i++) for (int j = 1; j <= cols; j++) vals[t++] = i * j;
        Arrays.sort(vals);
        return vals[k - 1];
    }
}

