static int cmpInt(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (p > q) - (p < q);
}

int kthInTable(int rows, int cols, int k) {
    int* vals = malloc((size_t) rows * cols * sizeof(int));
    int t = 0;
    for (int i = 1; i <= rows; i++) for (int j = 1; j <= cols; j++) vals[t++] = i * j;
    qsort(vals, t, sizeof(int), cmpInt);
    int answer = vals[k - 1];
    free(vals);
    return answer;
}

