class Solution {
    public int kthInTable(int rows, int cols, int k) {
        if (rows > cols) { int t = rows; rows = cols; cols = t; }
        int lo = 1, hi = rows * cols;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long count = 0;
            for (int i = 1; i <= rows; i++) count += Math.min(mid / i, cols);
            if (count >= k) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

